SELECT product_id, CASE WHEN unit_price >= 420 THEN 'high' WHEN unit_price >= 180 THEN 'mid' ELSE 'low' END AS unit_price_bucket, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 2 THEN 'mid' ELSE 'low' END AS quantity_bucket, COUNT(DISTINCT unit_price) AS unique_products, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM order_items WHERE product_id IS NOT NULL GROUP BY product_id, CASE WHEN unit_price >= 420 THEN 'high' WHEN unit_price >= 180 THEN 'mid' ELSE 'low' END, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 2 THEN 'mid' ELSE 'low' END;
